const b = $input.first().json.body || {};
const id = Number(b.jobId !== undefined ? b.jobId : b.job_id);
if (!Number.isInteger(id) || id <= 0) throw new Error('jobId must be a positive integer');
const pkg = String(b.package || '').trim();
const type = String(b.type || '').trim();
const member = String(b.member || '').trim();
const tfm = String(b.tfm || 'net8.0').trim().toLowerCase();
if (!/^[A-Za-z0-9._-]{1,100}$/.test(pkg)) throw new Error('package must be a NuGet id, got ' + JSON.stringify(pkg).slice(0, 60));
if (!/^[A-Za-z0-9_.`]{1,200}$/.test(type)) throw new Error('type must be a type or method name, got ' + JSON.stringify(type).slice(0, 60));
if (!/^[A-Za-z0-9_.`]{0,100}$/.test(member)) throw new Error('member must be a member name, got ' + JSON.stringify(member).slice(0, 60));
if (!/^(net\d+\.\d+|netstandard\d\.\d|netcoreapp\d\.\d)$/.test(tfm)) throw new Error('tfm must be a target framework moniker, got ' + JSON.stringify(tfm).slice(0, 30));
return [{ json: { jobId: id, package: pkg, type: type, member: member, tfm: tfm } }];
